// ---- Switch sources on/off to test them separately (saves Apify credits) ----
const DEFAULTS = {
  courses: true,         // Coursera via Apify
  practice: true,        // Google search via Apify (+ LeetCode for software roles)
  interviews: true,      // Google search + Glassdoor via Apify
  plan: true,            // final Claude step that builds the prep plan
  prep_days: 14,
  courses_per_query: 4,
  glassdoor_max_interviews: 30,  // fetched per company; the 10 most relevant are kept
  leetcode_per_tag: 3
};

return $input.all().map(i => ({
  json: { ...i.json, settings: { ...DEFAULTS, ...(i.json.settings || {}) } }
}));

const res = $json;
let text = '';
if (Array.isArray(res.content)) text = res.content.filter(c => c.type === 'text').map(c => c.text).join('\n');
else text = res.text || res.merged_response || '';

const match = text.match(/\{[\s\S]*\}/);
let analysis;
try { analysis = JSON.parse(match ? match[0] : text); }
catch (e) { throw new Error('Analysis is not valid JSON: ' + text.slice(0, 300)); }

const src = $('Loop jobs').item.json;  // keeps user_job_row_id, auth_user_id, job, candidate, settings
return { json: { ...src, analysis } };

// Short summary per job for the calling pipeline; the full plan is stored in user_jobs (prep_* columns)
return $input.all().map(i => ({ json: {
  user_job_row_id: i.json.id ?? i.json.user_job_row_id,
  job_id: i.json.job_id,
  prep_status: i.json.prep_status ?? 'not_saved',
  prep_data_quality: i.json.prep_data_quality
} }));

const ctx = $input.first().json;
let queries = (ctx.analysis.course_queries || []).filter(Boolean).slice(0, 2);
if (!queries.length) queries = [ctx.job.title];
return queries.map(q => ({ json: { searchQuery: q, maxItems: ctx.settings.courses_per_query, language: 'english' } }));

const ctx = $('Courses on?').first().json;
const rows = $input.all().map(i => i.json);
const errors = rows.filter(r => r && r.error).map(r => r.error.message || String(r.error));
const seen = new Set();
const courses = [];
for (const c of rows) {
  if (!c || c.error || !c.name || !c.url || seen.has(c.url)) continue;
  seen.add(c.url);
  courses.push({
    title: c.name,
    url: c.url,
    provider: c.partnerName,
    rating: c.rating,
    reviews: c.reviewCount,
    level: c.difficulty,
    duration: c.duration,
    skills: (c.skills || []).slice(0, 8)
  });
}
return [{ json: { ...ctx, courses, courses_errors: errors } }];

const ctx = $input.first().json;
let queries = (ctx.analysis.practice_search_queries || []).filter(Boolean).slice(0, 2);
if (!queries.length) queries = [`${ctx.job.title} interview questions`];
return [{ json: { queries: queries.join('\n'), maxPagesPerQuery: 1, languageCode: 'en', mobileResults: false, saveHtml: false, saveHtmlToKeyValueStore: false, includeUnfilteredResults: false } }];

const ctx = $('Practice on?').first().json;
const errors = [];
const seen = new Set();
const practice_web = [];
for (const i of $input.all()) {
  const page = i.json;
  if (!page) continue;
  if (page.error) { errors.push(page.error.message || String(page.error)); continue; }
  for (const r of (page.organicResults || [])) {
    if (!r.url || seen.has(r.url)) continue;
    seen.add(r.url);
    practice_web.push({ title: r.title, url: r.url, snippet: r.description, query: page.searchQuery ? page.searchQuery.term : undefined });
  }
}
return [{ json: { ...ctx, practice_web: practice_web.slice(0, 10), practice_leetcode: [], practice_errors: errors } }];

const ctx = $input.first().json;
const QUERY = `query questionList($categorySlug: String, $limit: Int, $skip: Int, $filters: QuestionListFilterInput) {
  questionList(categorySlug: $categorySlug, limit: $limit, skip: $skip, filters: $filters) {
    totalNum
    data { title titleSlug difficulty acRate isPaidOnly topicTags { slug } }
  }
}`;
return (ctx.analysis.leetcode_tags || []).slice(0, 3).map(tag => ({
  json: { tag, body: { operationName: 'questionList', query: QUERY, variables: { categorySlug: '', skip: 0, limit: 50, filters: { tags: [tag] } } } }
}));

const base = $('Collect web practice').first().json;
const requests = $('Build LeetCode requests').all();
const perTag = base.settings.leetcode_per_tag || 3;
const out = [];
const errors = [];
const seen = new Set();
$input.all().forEach((item, idx) => {
  const r = item.json;
  const tag = requests[idx] ? requests[idx].json.tag : undefined;
  if (!r || r.error || r.errors) { errors.push((r && r.error && r.error.message) || JSON.stringify(r && r.errors).slice(0, 200)); return; }
  // LeetCode returns problems in problem-number order: low numbers are the classic, most-discussed ones
  const list = ((r.data && r.data.questionList && r.data.questionList.data) || []).filter(q => !q.isPaidOnly && !seen.has(q.titleSlug));
  const easy = list.filter(q => q.difficulty === 'Easy');
  const medium = list.filter(q => q.difficulty === 'Medium');
  const picks = [...easy.slice(0, 1), ...medium.slice(0, perTag - 1)];
  for (const q of picks) {
    seen.add(q.titleSlug);
    out.push({ title: q.title, url: `https://leetcode.com/problems/${q.titleSlug}/`, difficulty: q.difficulty, tag });
  }
});
return [{ json: { ...base, practice_leetcode: out, practice_leetcode_errors: errors } }];

const base = $('Collect web interviews').first().json;
const all = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const errors = all.filter(r => r.error).map(r => r.error.message || String(r.error));
const rows = all.filter(r => !r.error && r.interviewId);

// Rank reports: similar job title and same region first
const words = s => String(s || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 2);
const roleWords = base.analysis.role_type === 'software'
  ? ['software', 'firmware', 'embedded', 'engineer', 'developer']
  : ['engineer', 'electrical', 'electronics', 'hardware', 'process', 'research', 'researcher', 'scientist'];
const target = new Set([...words(base.job.title), ...roleWords]);
const place = new Set(words(base.job.location));
const score = r => {
  let s = 0;
  for (const w of words(r.jobTitle)) if (target.has(w)) s += 2;
  for (const w of words(r.location)) if (place.has(w)) s += 1;
  if ((r.questions || []).length) s += 1;
  return s;
};
const interviews_glassdoor = rows
  .map(r => ({ r, s: score(r) }))
  .sort((a, b) => b.s - a.s || String(b.r.reviewDateTime).localeCompare(String(a.r.reviewDateTime)))
  .slice(0, 10)
  .map(({ r, s }) => ({
    job_title: r.jobTitle,
    location: r.location,
    date: String(r.reviewDateTime || '').slice(0, 10),
    difficulty: r.difficulty,
    outcome: r.outcome,
    process: String(r.processDescription || '').slice(0, 800),
    advice: r.advice,
    questions: (r.questions || []).map(q => (q && q.question) || q).slice(0, 5),
    url: r.url,
    relevance: s
  }));
return [{ json: { ...base, interviews_glassdoor, glassdoor_errors: errors } }];

const ctx = $input.first().json;
const company = ctx.analysis.company_search_name || ctx.job.companyName;
let queries = (ctx.analysis.interview_search_queries || []).filter(Boolean).slice(0, 2);
if (!queries.length) queries = [`${company} ${ctx.job.title} interview experience`];
// extra query to find the company's own Glassdoor page (used to pick the right company on Glassdoor)
queries.push(`site:glassdoor.com "${company}" interview questions`);
return [{ json: { queries: queries.join('\n'), maxPagesPerQuery: 1, languageCode: 'en', mobileResults: false, saveHtml: false, saveHtmlToKeyValueStore: false, includeUnfilteredResults: false } }];

const ctx = $('Interviews on?').first().json;
const company = (ctx.analysis.company_search_name || ctx.job.companyName).toLowerCase();
const errors = [];
const seen = new Set();
const interviews_web = [];
const gdIds = {};
for (const i of $input.all()) {
  const page = i.json;
  if (!page) continue;
  if (page.error) { errors.push(page.error.message || String(page.error)); continue; }
  for (const r of (page.organicResults || [])) {
    if (!r.url || seen.has(r.url)) continue;
    seen.add(r.url);
    // Glassdoor employer id from URLs like ...-E773880.htm or ...EI_IE773880...
    const m = r.url.match(/glassdoor\.[a-z.]+\/.*?(?:EI_IE|-E)(\d+)/i);
    if (m && String(r.title || '').toLowerCase().includes(company.split(' ')[0])) gdIds[m[1]] = (gdIds[m[1]] || 0) + 1;
    interviews_web.push({ title: r.title, url: r.url, snippet: r.description });
  }
}
const bestId = Object.keys(gdIds).sort((a, b) => gdIds[b] - gdIds[a])[0];
const glassdoor_url = bestId ? `https://www.glassdoor.com/Interview/Company-Interview-Questions-E${bestId}.htm` : null;
return [{ json: { ...ctx, interviews_web: interviews_web.slice(0, 8), interviews_web_errors: errors, glassdoor_url } }];

const ctx = $input.first().json;
const trim = (s, n) => String(s || '').slice(0, n);
const materials = {
  courses: (ctx.courses || []).slice(0, 8),
  practice_web: (ctx.practice_web || []).slice(0, 8).map(p => ({ title: p.title, url: p.url, snippet: trim(p.snippet, 200) })),
  practice_leetcode: ctx.practice_leetcode || [],
  interviews_glassdoor: (ctx.interviews_glassdoor || []).slice(0, 10),
  interviews_web: (ctx.interviews_web || []).slice(0, 8).map(p => ({ title: p.title, url: p.url, snippet: trim(p.snippet, 300) }))
};
const prompt = `PREP DAYS: ${ctx.settings.prep_days}

JOB
Title: ${ctx.job.title}
Company: ${ctx.job.companyName}
Location: ${ctx.job.location}
Description: ${trim(ctx.job.description, 5000)}

CANDIDATE
${JSON.stringify(ctx.candidate)}

JOB ANALYSIS
${JSON.stringify(ctx.analysis)}

RETRIEVED MATERIALS (only use these URLs)
${JSON.stringify(materials)}`;
return [{ json: { prompt, ctx } }];

const ctx = $('Prepare plan input').first().json.ctx;
const res = $input.first().json;
const text = Array.isArray(res.content) ? res.content.filter(c => c.type === 'text').map(c => c.text).join('\n') : (res.text || '');
const m = text.match(/\{[\s\S]*\}/);
let plan;
try { plan = JSON.parse(m ? m[0] : text); }
catch (e) { throw new Error('Plan is not valid JSON: ' + text.slice(0, 300)); }

const md = [
  `# Interview prep: ${ctx.job.title} at ${ctx.job.companyName}`,
  '', '## Skill gaps', ...(ctx.analysis.skill_gaps || []).map(g => `- ${g.skill}: ${g.why}`),
  '', '## Courses', ...(plan.selected_courses || []).map(c => `- [${c.title}](${c.url}): ${c.why}`),
  '', '## Practice', ...(plan.selected_practice || []).map(p => `- [${p.title}](${p.url}) (${p.type}): ${p.why}`),
  '', '## What the interview looks like', ...(plan.interview_insights || []).map(i => `- ${i.insight} ([source](${i.source_url}))`),
  '', '## Likely questions', ...(plan.likely_questions || []).map(q => `- ${q.question} (${q.source}). Hint: ${q.answer_hint}`),
  '', `## ${ctx.settings.prep_days}-day plan`, ...(plan.plan || []).map(d => `- Day ${d.day}, ${d.focus}: ${(d.tasks || []).join('; ')}`)
].join('\n');

return [{ json: {
  user_job_row_id: ctx.user_job_row_id,
  auth_user_id: ctx.auth_user_id,
  job_id: ctx.job.id,
  job_title: ctx.job.title,
  company: ctx.job.companyName,
  job_url: ctx.job.url,
  role_type: ctx.analysis.role_type,
  skill_gaps: ctx.analysis.skill_gaps || [],
  courses: plan.selected_courses || [],
  practice: plan.selected_practice || [],
  interview_insights: plan.interview_insights || [],
  likely_questions: plan.likely_questions || [],
  plan: plan.plan || [],
  plan_markdown: md,
  data_quality: plan.data_quality,
  materials_found: {
    courses: (ctx.courses || []).length,
    practice_web: (ctx.practice_web || []).length,
    leetcode: (ctx.practice_leetcode || []).length,
    glassdoor: (ctx.interviews_glassdoor || []).length,
    interviews_web: (ctx.interviews_web || []).length
  }
} }];

// Manual test: starts the parallel workers for this user.
// redo: true rebuilds plans that already exist; max_jobs limits jobs per worker (0 = all).
return [{ json: { auth_user_id: '00000000-0000-0000-0000-000000000000', redo: false, max_jobs: 0 } }];

// This worker's share of the user's recommended jobs (user-vacancy pairs without a prep plan).
const cfg = $('When called by pipeline').first().json;
const lane = Number(cfg.lane) || 0;
const lanes = Number(cfg.lanes) || 1;
const REDO = cfg.redo === true;          // rebuild even if prep_status = 'ready'
const MAX_JOBS = Number(cfg.max_jobs) || 0; // 0 = no limit

const seen = new Set();
const rows = $input.all().map(i => i.json)
  .filter(r => r && r.job_id && r.hidden !== true)
  .filter(r => Number(r.id) % lanes === lane)          // stable split by row id
  .filter(r => REDO || r.prep_status !== 'ready')
  .filter(r => !seen.has(r.job_id) && seen.add(r.job_id));
rows.sort((a, b) => (b.priority_score ?? 0) - (a.priority_score ?? 0) || (b.match_score ?? 0) - (a.match_score ?? 0));

const picked = MAX_JOBS > 0 ? rows.slice(0, MAX_JOBS) : rows;
return picked.map(r => ({ json: { user_job_row_id: r.id, job_id: r.job_id } }));

const user = $('Get user').first().json;
const cfg = $('When called by pipeline').first().json;
const picks = $('Pick jobs').all().map(i => i.json);
const jobsById = {};
for (const i of $input.all()) if (i.json && i.json.job_id) jobsById[i.json.job_id] = i.json;

const parse = s => { if (!s) return []; try { return JSON.parse(s); } catch (e) { return [s]; } };
const candidate = {
  name: [user.first_name, user.last_name].filter(Boolean).join(' '),
  location: [user.location, user.country].filter(Boolean).join(', '),
  target_roles: parse(user.target_roles_json),
  summary: user.profile_summary,
  skills: parse(user.skills_json),
  experience: parse(user.experience_json),
  education: parse(user.education_json),
  previous_companies: parse(user.previous_companies_json),
  cv_text: String(user.cv_text || '').slice(0, 6000)
};

const out = [];
for (const p of picks) {
  const j = jobsById[p.job_id];
  if (!j) continue;
  out.push({ json: {
    user_job_row_id: p.user_job_row_id,
    auth_user_id: user.auth_user_id,
    job: {
      id: j.job_id,
      title: j.title,
      companyName: j.company_name,
      companyUrl: j.company_url,
      location: j.location,
      url: j.job_url,
      experienceLevel: j.seniority,
      description: j.description
    },
    candidate,
    settings: { redo: cfg.redo === true }
  } });
}
return out;

const out = $('Format output').first().json;
const row = $input.first().json || {};
return [{ json: {
  user_job_row_id: row.id ?? out.user_job_row_id,
  job_id: out.job_id,
  prep_status: row.id ? 'already_done' : 'pair_not_found',
  prep_data_quality: row.prep_data_quality
} }];

// ---- Number of parallel workers. Apify allows 5 concurrent Actor runs (checked 2026-09-27: maxConcurrentActorJobs = 5).
// Default 3; the automatic pipeline (Process User) passes lanes = 2 because Referals runs at the same time with 2 workers.
const src = $input.first().json;
const LANES = Math.max(1, Math.min(3, Number(src.lanes) || 3));
if (!src.auth_user_id) throw new Error('auth_user_id is required');
return Array.from({ length: LANES }, (_, i) => ({ json: {
  auth_user_id: src.auth_user_id,
  lane: i,
  lanes: LANES,
  redo: !!src.redo,
  max_jobs: src.max_jobs || 0
} }));

const first = $('Fan out').first().json;
return [{ json: {
  auth_user_id: first.auth_user_id,
  status: 'started',
  workers: $('Fan out').all().length,
  note: 'Prep plans are written to user_jobs (prep_* columns) as each job finishes.'
} }];
